 if(m=take(/ (\d+(?:\.\d+)?) ?(?:free )?(h|hr|hrs|hour|hours) /))P.ctx.T=Math.round(parseFloat(m[1])*60);
 else if(m=take(/ (\d+) ?(?:free )?(m|min|mins|minute|minutes) /))P.ctx.T=+m[1];
 else if(take(/ half an hour /))P.ctx.T=30;else if(take(/ an hour /))P.ctx.T=60;else if(take(/ a few minutes /))P.ctx.T=10;
 if(take(/ before dinner /)){const until=Math.round((((19-C.h)%24+24)%24)*60/5)*5;P.ctx.T=Math.min(P.ctx.T||999,Math.max(5,until));P.chips.push("until dinner ≈19:00")}
 if(take(/ (tired|exhausted|sleepy|drained|low energy|knackered|fatigued) /))P.ctx.E=.2;else if(take(/ (energetic|energised|energized|fresh|wired|full of energy) /))P.ctx.E=.85;
 if(/ (avoid|dangerous|danger|risky|unsafe|risk|should not|shouldnt) /.test(q)){P.mode="avoid";P.view="tail";q=q.replace(/ (what )?(should i )?(avoid|dangerous|danger|risky|unsafe|risk|is this) /g," ")}
 if(take(/ (large|big|huge) upside | opens? (up )?possibilit(y|ies) | right tail | convex | optionality | big win /)){P.mode=P.mode||"optionality";P.view="optionality"}
 if(take(/ (something )?new | try something | explore /)){P.ctx.N=.85;P.view=P.view||"explore"}
 if(take(/ (useful|productive) /)){P.weights={car:1.6,hom:1.4,lrn:1.3,joy:.6};P.chips.push("useful: work, maintenance, learning up")}
